// 意味が近く、選択肢に一緒に並べると正解が一つに決まらないフレーズのまとまり
const SIMILAR_GROUPS = [
  ['ep11', 'ep12', 'ep18'],
  ['ep15', 'ep16'],
  ['ep31', 'ep32'],
  ['ep42', 'ep54'],
  ['ep71', 'ep72'],
  ['ep40', 'ep79'],
];

const WORD_ROWS = WORDS_RAW.trim().split('\n');
export const ENGLISH_WORD_STAGES = stagesFor(WORD_ROWS.length, 'en'); // 行の順番でレベルに分ける（levels.js）

export const ENGLISH_WORDS = WORD_ROWS.map((line, i) => {
  const stage = stageIdAt(ENGLISH_WORD_STAGES, i + 1);
  const [id, en, ipa, ja, alts, pos, category, hint] = line.split('|');
  return {
    lang: 'en',
    kind: 'word',
    id,
    es: en, // 学習する言語の表記。項目名は全言語共通で es を使う
    ipa,
    ja,
    accepted: [ja, ...(alts ? alts.split('/') : [])],
    pos,
    article: '',
    category,
    hint: hint || '',
    stage,
    level: ENGLISH_WORD_STAGES.find((st) => st.id === stage).level,
    order: i + 1,
    frequencyRank: i + 1,
    source: ENGLISH_SOURCE,
  };
});


export const ENGLISH_PHRASES = PHRASES_RAW.trim().split('\n').map((line, i) => {
  const [id, en, ja, alts, category, note] = line.split('|');
  const group = SIMILAR_GROUPS.findIndex((g) => g.includes(id));
  return {
    lang: 'en',
    similarGroup: group >= 0 ? `epg${group}` : '',
    kind: 'phrase',
    id,
    es: en,
    ja,
    accepted: [ja, ...(alts ? alts.split('/') : [])],
    category,
    hint: '',
    note: note || '',
    stage: 1,
    level: 'A1',
    order: i + 1,
    source: ENGLISH_SOURCE,
  };
});
